<?php
require __DIR__.'/ui.php';role(['admin','gerente','vendedor']);$p=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$d=[trim($_POST['name']),trim($_POST['whatsapp']),trim($_POST['email']),$_POST['birthday']?:null,trim($_POST['address']),trim($_POST['notes'])];if($id){$p->prepare("UPDATE customers SET name=?,whatsapp=?,email=?,birthday=?,address=?,notes=? WHERE id=?")->execute([...$d,$id]);audit('update','customers',$id);}else{$p->prepare("INSERT INTO customers(name,whatsapp,email,birthday,address,notes)VALUES(?,?,?,?,?,?)")->execute($d);audit('create','customers',(int)$p->lastInsertId());}go('customers.php');}
$edit=null;if(isset($_GET['edit'])){$s=$p->prepare("SELECT * FROM customers WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$p->query("SELECT c.*,COUNT(o.id) orders_count,COALESCE(SUM(o.total),0) spent FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id ORDER BY c.name")->fetchAll();page_head('Clientes');?>
<div class="grid g2"><div class="card"><h2><?=$edit?'Editar':'Novo'?> cliente</h2><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$edit['id']??''?>"><div class="grid g2"><div><label>Nome</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div><label>WhatsApp</label><input name="whatsapp" value="<?=e($edit['whatsapp']??'')?>"></div><div><label>E-mail</label><input name="email" value="<?=e($edit['email']??'')?>"></div><div><label>Aniversário</label><input type="date" name="birthday" value="<?=e($edit['birthday']??'')?>"></div></div><label>Endereço</label><textarea name="address"><?=e($edit['address']??'')?></textarea><label>Observações</label><textarea name="notes"><?=e($edit['notes']??'')?></textarea><button class="primary">Salvar</button></form></div>
<div class="card"><h2>CRM</h2><p>Cadastre aniversário de casamento, namoro, filhos, mãe, esposa e outras datas recorrentes em <a class="btn" href="crm.php">Datas especiais</a>.</p></div></div>
<div class="card"><div class="table"><table><tr><th>Cliente</th><th>WhatsApp</th><th>Pedidos</th><th>Total gasto</th><th>Pontos</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['whatsapp'])?></td><td><?=$r['orders_count']?></td><td><?=money($r['spent'])?></td><td><?=$r['points']?></td><td><a class="btn" href="?edit=<?=$r['id']?>">Editar</a></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>